{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California tenant screening fee cap and applicant rights","requirement":"A landlord may not charge a screening fee above the 2026 cap of $68.96, may not charge a fee if no unit is available, must provide a receipt and credit report copy, refund unused amounts, and use a reusable screening report an applicant provides.","key_value":"$68.96 (2026)","coverage_conditions":"Applies to screening fees charged to applicants for residential rental units in California; a fee may not be charged if no rental unit is actually available.","applicability":{"conditions":[],"per_tenancy":"Charging a screening fee to an applicant; a reusable screening report the applicant provides; no rental unit actually available","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026","valid_through":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is $68.96","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley tenant screening fee disclosure and ban on non-refundable renewal fees","requirement":"An owner or agent must give an applicant a tenant screening fee rights statement and the state fee cap before taking a screening fee, and may not charge an existing tenant a non-refundable fee to renew a tenancy.","key_value":null,"coverage_conditions":"Chapter 13.78 applies to all residential rental agreements, regardless of any contractual language to the contrary.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":"Any provision of an existing rental agreement or lease that violates the provisions of this chapter are unenforceable.","effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.78","quoted_span":"An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part, including any fee associated with the departure of a roommate or to request to add or replace a roommate in a pre-existing household.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
